head.script:
scwin.checkPlaceHolder = function() {
    var is_ie89 = navigator.appVersion.indexOf("MSIE 8.") != -1 ||
        navigator.appVersion.indexOf("MSIE 9.") != -1;
    if (is_ie89) {
        return ((j) => j.length ? j : $('#mf_input1'))($('#input1')).val() == "프로퍼티" && ((j) => j.length ? j : $('#mf_input2'))($('#input2')).val() == "API";
    } else {
        return ((j) => j.length ? j : $('#mf_input1'))($('#input1')).attr("placeholder") == "프로퍼티" && ((j) => j.length ? j : $('#mf_input2'))($('#input2')).attr("placeholder") == "API";
    }
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    input2.setPlaceholder("API");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 28-Feb-2018
    //end
}
